"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";
import { channel } from "./patches/channel.patch.ts";

export default sketch(($) => {
  const route = $.geometry.polyline("route", {
    vertices: [{
      key: "start",
      position: [0, 0],
    }, {
      key: "bend",
      position: [30, 0],
    }, {
      key: "bend2",
      position: [30, 20],
    }, {
      key: "end",
      position: [60, 20],
    }],
    closed: false,
    branchDirections: [[1, 0], [0, 1], [1, 0]],
  });
  const wet = $.use("wet", channel, {
    polyline: route,
    width: mm(6),
    bendRadius: mm(5),
  });
  return {
    route: route,
    wet: wet,
  };
});

